export default function QuestionItem({ question }) {
  return (
    <div className="p-3 border rounded-lg bg-gray-50 dark:bg-zinc-700">
      <p className="font-medium">❓ {question.question}</p>
      {question.answer ? (
        <p className="text-green-700 mt-1">💬 {question.answer}</p>
      ) : (
        <p className="text-gray-400 mt-1">در انتظار پاسخ…</p>
      )}
      <span className="text-xs text-gray-500">{question.date}</span>
    </div>
  );
}
